SF = ["‘{w}’ میں لاحقہ ہے:","لفظ ‘{w}’ کا لاحقہ منتخب کیجیے:","درج ذیل لفظ کے آخر میں لگنے والا حصہ (لاحقہ) کون سا ہے؟<br>{w}"]

def pick(pool, ans, word, i, start_end):
    flat = word.replace(" ", "")
    out, k = [], 0
    while len(out) < 3:
        d = pool[(i * 5 + k * 7 + 3) % len(pool)]
        k += 1
        if d == ans or d in out: continue
        if start_end == "start" and flat.startswith(d): continue
        if start_end == "end" and flat.endswith(d): continue
        out.append(d)
    return out

